(()=>{'use strict';const body=$('#np-lyrics-body'),status=$('#np-lyrics-status'),line=$('#np-lyric'),cache=new Map();let version=0,controller=null,activeTrack=null,requestKey='',manual=false,lines=[],active=-1,timed=false;const key=t=>[t.title,t.artist,t.album||''].join('|');
function parse(text){let offset=0;const found=String(text).match(/\[offset:([+-]?\d+)\]/i);if(found)offset=Number(found[1])/1000;const rows=[];for(const raw of String(text).split(/\r?\n/)){const text=raw.replace(/\[[^\]]*\]/g,'').trim();for(const m of raw.matchAll(/\[(\d{1,3}):([0-5]\d(?:\.\d{1,3})?)\]/g))rows.push({time:Math.max(0,Number(m[1])*60+Number(m[2])+offset),text})}return rows.sort((a,b)=>a.time-b.time).slice(0,2000)}
function show(data){lines=data.synced?parse(data.synced):[];timed=!!lines.length;active=-2;body.replaceChildren();if(data.instrumental){status.textContent='Instrumental · LRCLIB';line.textContent='Instrumental recording';return}if(timed){status.textContent='Synced lyrics · '+(data.source||'LRCLIB');for(const row of lines){const p=document.createElement('p');p.textContent=row.text||'♪';body.append(p)}}else if(data.plain){status.textContent='Lyrics · '+(data.source||'LRCLIB')+' · timing unavailable';const p=document.createElement('p');p.className='lyrics-plain';p.textContent=data.plain;body.append(p);line.textContent='Lyrics available in the lyrics panel.'}else{status.textContent='No matching lyrics available.';line.textContent='Lyrics unavailable for this recording.'}}
function reset(track){version++;controller?.abort();controller=null;activeTrack=track;requestKey='';manual=false;lines=[];timed=false;active=-1;body.replaceChildren();status.textContent='Lyrics appear here when available.';line.textContent='Looking for lyrics when playback starts…'}
async function load(track,duration){if(!track)return;if(activeTrack!==track)reset(track);if(manual)return;if(track.live){status.textContent='Live radio has no identified song for lyrics lookup.';line.textContent='Live radio · song lyrics unavailable';return}if(!track.artist||/^Local file/i.test(track.artist)){status.textContent='Import an LRC file for local audio without artist metadata.';line.textContent='Add an LRC file for synced lyrics.';return}
 const requestDuration=Number(track.duration)||Number(duration)||0;if(!Number.isFinite(requestDuration)||requestDuration<=0){status.textContent='Waiting for track information…';return}const id=key(track)+'|'+Math.round(requestDuration);if(requestKey===id)return;requestKey=id;const mine=version;if(cache.has(id)){show(cache.get(id));return}const task=new AbortController();controller=task;const timeout=setTimeout(()=>task.abort(),10000);status.textContent='Finding lyrics…';line.textContent='Finding lyrics…';
 try{const params=new URLSearchParams({title:track.title,artist:track.artist});if(track.album)params.set('album',track.album);if(Number.isFinite(requestDuration)&&requestDuration>0)params.set('duration',String(requestDuration));const response=await fetch('/api/lyrics?'+params,{signal:task.signal});const data=await response.json();if(mine!==version)return;if(!response.ok)throw Error(data.error||'Lyrics unavailable.');cache.set(id,data);if(cache.size>40)cache.delete(cache.keys().next().value);show(data)}catch(error){if(mine!==version)return;requestKey='';status.textContent=error.name==='AbortError'?'Lyrics lookup timed out. Retry or import an LRC file.':error.message;line.textContent='Lyrics unavailable right now.'}finally{clearTimeout(timeout)}}
function sync(seconds,visible){if(!timed||!visible)return;let index=-1;for(let i=0;i<lines.length;i++){if(lines[i].time>seconds)break;index=i}if(index===active)return;if(active>=0)body.children[active]?.classList.remove('active');active=index;line.textContent=index>=0?lines[index].text||'♪':'Lyrics begin shortly.';if(index>=0){const element=body.children[index];element?.classList.add('active');if(element&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const target=element.offsetTop-body.clientHeight*.4;body.scrollTo({top:Math.max(0,target),behavior:'smooth'})}}}
$('#np-lyrics').onclick=()=>{$('#np-lyrics-pane').hidden=false;$('#np-lyrics-pane').scrollIntoView({block:'nearest',behavior:'smooth'});load(activeTrack,audio.duration)};$('#np-import-lyrics').onclick=()=>$('#lyrics-file').click();$('#np-retry-lyrics').onclick=()=>{if(activeTrack){manual=false;requestKey='';cache.clear();load(activeTrack,audio.duration)}};
$('#lyrics-file').onchange=async e=>{const file=e.target.files[0],track=activeTrack;if(!file)return;if(file.size>1024*1024){e.target.value='';return toast('Use an LRC file smaller than 1 MB.')}try{const text=await file.text();if(activeTrack!==track)return;version++;controller?.abort();manual=true;show({synced:text,source:'Imported LRC'});if(!timed){status.textContent='No LRC timestamps found in this file.';line.textContent='Import an LRC file with timestamps.'}}catch{status.textContent='This lyrics file could not be read.'}finally{e.target.value=''}};
window.OktawkaLyrics={reset,load,sync,parse};
})();
